<?php $pageTitle = 'Customer dashboard'; ?>
<section class="page-intro"><div class="intro-inner"><span class="eyebrow">Customer dashboard</span><h1>Welcome, <?= rc_e($user['full_name']) ?>.</h1><p>Review upcoming events, reservation status, payment balances, and account notifications.</p></div></section>
<section class="content-section"><div class="dashboard-actions"><a class="button" href="<?= rc_url('reservation') ?>">Start a reservation</a><button class="button button-secondary" type="button" data-dialog-title="Account details" data-dialog-text="Use the account form below to update your name, email, phone number, and address.">Account help</button></div><div class="dashboard-grid"><section class="surface"><div class="surface-heading"><h2>My reservations</h2><span><?= count($orders) ?> total</span></div><?php if ($orders): ?><div class="table-wrap"><table><thead><tr><th>Booking</th><th>Event</th><th>Package</th><th>Total</th><th>Paid / Balance</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($orders as $order): ?><tr><td>#RZ-<?= (int) $order['id'] ?></td><td><?= rc_e($order['event_date']) ?><small><?= rc_e(substr((string) $order['event_start_time'], 0, 5)) ?>–<?= rc_e(substr((string) $order['event_end_time'], 0, 5)) ?></small></td><td><?= rc_e($order['package_name'] ?: $order['dining_tier']) ?></td><td><?= rc_money(rc_cents($order['total_price'])) ?><small>Deposit <?= rc_money(rc_cents($order['down_payment_due'])) ?></small></td><td><?= rc_money(rc_cents($order['amount_paid'])) ?><small>Due <?= rc_money(rc_cents($order['balance_due'])) ?></small></td><td><span class="status status-<?= rc_e(strtolower(str_replace(' ', '-', $order['status']))) ?>"><?= rc_e($order['status']) ?></span><small><?= rc_e($order['payment_status']) ?></small><?php if (in_array($order['status'], ['Confirmed','Processing','Completed'], true)): ?><small>Food update: <?= rc_e($order['delivery_status'] ?? 'Not Started') ?></small><?php endif; ?></td><td><a class="text-link" href="<?= rc_url('reservation-view', ['id' => $order['id']]) ?>">Details</a></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><strong>No reservations yet</strong>Browse active packages and submit your first event request.</div><?php endif; ?></section>
<section class="surface" id="customer-notifications"><div class="surface-heading"><h2>Notifications</h2><span><?= count(array_filter($notifications, fn ($n) => !$n['read_at'])) ?> unread</span></div><?php if ($notifications): ?><div class="notification-list"><?php foreach ($notifications as $notification): ?><article class="notification <?= $notification['read_at'] ? '' : 'unread' ?>"><strong><?= rc_e($notification['notification_type']) ?></strong><p><?= rc_e($notification['message']) ?></p><time><?= rc_e($notification['created_at']) ?></time></article><?php endforeach; ?></div><form method="post" action="<?= rc_e(rc_endpoint()) ?>"><?= rc_csrf_field() ?><input type="hidden" name="action" value="mark-read"><button class="button button-secondary" type="submit">Mark all read</button></form><?php else: ?><p class="muted">Reservation and payment updates will appear here.</p><?php endif; ?></section></div>
<section class="surface account-surface"><div class="surface-heading"><h2>Account details</h2><span>Private to your account</span></div><form class="booking-grid" method="post" action="<?= rc_e(rc_endpoint()) ?>"><?= rc_csrf_field() ?><input type="hidden" name="action" value="profile"><div class="field"><label for="profile-name">Full name</label><input class="input-field" id="profile-name" name="full_name" maxlength="120" required value="<?= rc_e($customer['full_name']) ?>"></div><div class="field"><label for="profile-email">Email</label><input class="input-field" id="profile-email" name="email" type="email" maxlength="254" required value="<?= rc_e($customer['email']) ?>"></div><div class="field"><label for="profile-phone">Mobile</label><input class="input-field" id="profile-phone" name="contact_number" type="tel" maxlength="30" required value="<?= rc_e($customer['contact_number']) ?>"></div><div class="field"><label for="profile-address">Address (optional)</label><input class="input-field" id="profile-address" name="address" maxlength="500" value="<?= rc_e($customer['address']) ?>"></div><div class="field-wide"><button class="button" type="submit">Save account details</button></div></form><p class="muted"><a class="text-link" href="<?= rc_url('password') ?>">Change password</a></p></section></section>
